    const events=[...new Set([...props.filter(p=>p.sport==='NFL'&&p.eventID).map(p=>p.eventID),...scheduleGames.filter(g=>g.leagueID==='NFL'&&Date.parse(g.status?.startsAt)<=Date.now()+7*86400000).map(g=>g.eventID)])].slice(0,16);
